busy-waiting.pseudocode:
def test_and_set(lock):  # 하드웨어 원자 명령이라 가정
    old = lock.value
    lock.value = 1
    return old

def acquire(lock):  # 스핀락 (TTAS)
    while True:
        while lock.value == 1:
            pass  # 바쁜 대기: 캐시된 값만 반복 확인
        if test_and_set(lock) == 0:
            return  # 획득 성공

def release(lock):
    lock.value = 0
